-- NEXIOS Modern Agents & Tools Pack 1.0.0
-- Generated 2026-07-24. Every imported item remains disabled.

DO $guard$
BEGIN
  IF to_regclass('public.skill_registry') IS NULL THEN
    RAISE EXCEPTION 'Apply the NEXIOS modern skills migration before this pack.';
  END IF;
  IF to_regclass('public.agent_definitions') IS NULL OR to_regclass('public.tool_registry') IS NULL THEN
    RAISE EXCEPTION 'NEXIOS agent_definitions and tool_registry are required.';
  END IF;
END
$guard$;

CREATE TABLE IF NOT EXISTS public.agent_skill_bindings (
  agent_id text NOT NULL REFERENCES public.agent_definitions(id) ON DELETE CASCADE,
  skill_id text NOT NULL REFERENCES public.skill_registry(id) ON DELETE CASCADE,
  priority integer NOT NULL DEFAULT 100 CHECK (priority BETWEEN 1 AND 1000),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (agent_id, skill_id)
);

CREATE TABLE IF NOT EXISTS public.skill_tool_bindings (
  skill_id text NOT NULL REFERENCES public.skill_registry(id) ON DELETE CASCADE,
  tool_id text NOT NULL REFERENCES public.tool_registry(id) ON DELETE CASCADE,
  required boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (skill_id, tool_id)
);

ALTER TABLE public.agent_skill_bindings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.skill_tool_bindings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_skill_bindings_read ON public.agent_skill_bindings;
CREATE POLICY agent_skill_bindings_read
  ON public.agent_skill_bindings FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS agent_skill_bindings_write ON public.agent_skill_bindings;
CREATE POLICY agent_skill_bindings_write
  ON public.agent_skill_bindings FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS skill_tool_bindings_read ON public.skill_tool_bindings;
CREATE POLICY skill_tool_bindings_read
  ON public.skill_tool_bindings FOR SELECT TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS skill_tool_bindings_write ON public.skill_tool_bindings;
CREATE POLICY skill_tool_bindings_write
  ON public.skill_tool_bindings FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

GRANT SELECT ON public.agent_skill_bindings TO authenticated;
GRANT SELECT ON public.skill_tool_bindings TO authenticated;
GRANT ALL ON public.agent_skill_bindings TO service_role;
GRANT ALL ON public.skill_tool_bindings TO service_role;

CREATE OR REPLACE FUNCTION public.install_nexios_modern_agents_tools(p_org_id uuid)
RETURNS jsonb
