  inserted_tools integer := 0;
  inserted_agents integer := 0;
  inserted_agent_skills integer := 0;
  inserted_skill_tools integer := 0;
BEGIN
  IF p_org_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'A valid explicit organization id is required.';
  END IF;

  WITH pack_rows AS (
    SELECT *
    FROM jsonb_to_recordset($tools$
