      name text,
      goal text,
      system_prompt text,
      permissions jsonb,
      tool_allowlist jsonb,
      memory_scope text,
      model text,
      enabled boolean,
      metadata jsonb
    )
  ), inserted AS (
    INSERT INTO public.agent_definitions (
      id, name, goal, system_prompt, permissions, tool_allowlist,
      memory_scope, model, enabled, metadata, org_id
    )
    SELECT
      x.id, x.name, x.goal, x.system_prompt,
      ARRAY(SELECT jsonb_array_elements_text(x.permissions)),
      ARRAY(SELECT jsonb_array_elements_text(x.tool_allowlist)),
      x.memory_scope, x.model, false, x.metadata, p_org_id
    FROM pack_rows x
    ON CONFLICT (id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO inserted_agents FROM inserted;

