$agent_skills$::jsonb) AS x(agentId text, skillId text, priority integer)
  ), inserted AS (
    INSERT INTO public.agent_skill_bindings (agent_id, skill_id, priority)
    SELECT x.agentId, x.skillId, x.priority
    FROM pack_rows x
    WHERE EXISTS (SELECT 1 FROM public.agent_definitions a WHERE a.id = x.agentId AND a.org_id = p_org_id)
      AND EXISTS (SELECT 1 FROM public.skill_registry s WHERE s.id = x.skillId)
    ON CONFLICT (agent_id, skill_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO inserted_agent_skills FROM inserted;

