$skill_tools$::jsonb) AS x(skillId text, toolId text, required boolean)
  ), inserted AS (
    INSERT INTO public.skill_tool_bindings (skill_id, tool_id, required)
    SELECT x.skillId, x.toolId, x.required
    FROM pack_rows x
    WHERE EXISTS (SELECT 1 FROM public.skill_registry s WHERE s.id = x.skillId)
      AND EXISTS (SELECT 1 FROM public.tool_registry t WHERE t.id = x.toolId AND t.org_id = p_org_id)
    ON CONFLICT (skill_id, tool_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO inserted_skill_tools FROM inserted;

  RETURN jsonb_build_object(
    'organization_id', p_org_id,
    'inserted_tools', inserted_tools,
    'inserted_agents', inserted_agents,
    'inserted_agent_skill_bindings', inserted_agent_skills,
    'inserted_skill_tool_bindings', inserted_skill_tools,
    'all_imports_enabled', false,
    'next_step', 'Implement and test connectors, then enable one item at a time.'
  );
END
$function$;

REVOKE ALL ON FUNCTION public.install_nexios_modern_agents_tools(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.install_nexios_modern_agents_tools(uuid) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.install_nexios_modern_agents_tools(uuid) TO service_role;

COMMENT ON FUNCTION public.install_nexios_modern_agents_tools(uuid) IS
  'Installs descriptor-only NEXIOS modern agents and tools for one explicit organization. Nothing is enabled.';
